"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[905],{6039(e,n,a){a.r(n),a.d(n,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>m});const i=JSON.parse('{"id":"part5-deep-learning-and-llms/ffn-canonical-merged","title":"Neural Networks (ANNs): From a Single Neuron to Multiclass Image Classification","description":"A student-friendly tutorial that reconstructs the lecture ideas: why neural networks exist, how they generalize linear models, why activation functions matter, how backpropagation works (chain rule!), and how this con...","source":"@site/docs/part5-deep-learning-and-llms/03-ffn-canonical-merged.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/03-ffn-canonical-merged","permalink":"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":3,"frontMatter":{"title":"Neural Networks (ANNs): From a Single Neuron to Multiclass Image Classification","slug":"/part5-deep-learning-and-llms/03-ffn-canonical-merged","description":"A student-friendly tutorial that reconstructs the lecture ideas: why neural networks exist, how they generalize linear models, why activation functions matter, how backpropagation works (chain rule!), and how this con...","sidebar_label":"3. FFN single-chapter reference","pagination_label":"3. FFN single-chapter reference","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"2. FFN training and debugging","permalink":"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging"},"next":{"title":"4. CNN convolution","permalink":"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution"}}');var t=a(4848),s=a(8453),o=a(8172);const r=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/03-ffn-canonical-merged.html","route":"/part5-deep-learning-and-llms/03-ffn-canonical-merged","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"Artificial Neural Networks (ANNs): from \u201cone neuron\u201d to multiclass models","title":"Neural Networks (ANNs): From a Single Neuron to Multiclass Image Classification","description":"A student-friendly tutorial that reconstructs the lecture ideas: why neural networks exist, how they generalize linear models, why activation functions matter, how backpropagation works (chain rule!), and how this con...","readingMinutes":13,"bodyClass":"","normalizeMath":false,"toc":[{"id":"why-how-why-this-topic-is-so-interesting","label":"Why? How? Why this topic is so interesting"},{"id":"from-logistic-regression-to-a-neuron","label":"From logistic regression to a \u201cneuron\u201d"},{"id":"from-one-neuron-to-layers-to-deep-networks","label":"From one neuron to layers to deep networks"},{"id":"neural-nets-as-geometry-solvers-why-linear-models-aren-t-enough","label":"Neural nets as geometry solvers: why linear models aren\u2019t enough"},{"id":"activation-functions-sigmoid-tanh-relu-and-why","label":"Activation functions: sigmoid \u2192 tanh \u2192 ReLU (and why)"},{"id":"how-models-learn-gradients-chain-rule-backprop-and-vanishing-gradients","label":"How models learn: gradients, chain rule, backprop, and vanishing gradients"},{"id":"three-tasks-and-their-final-layer-activations","label":"Three tasks & their final-layer activations"},{"id":"multiclass-classification-softmax-cross-entropy-and-stability","label":"Multiclass classification: softmax + cross-entropy (and stability)"},{"id":"how-images-are-represented-in-a-computer-rgb-grayscale-quantization-flattening","label":"How images are represented in a computer (RGB, grayscale, quantization, flattening)"},{"id":"mnist-tutorial-multiclass-ann-with-dataloader-mini-batches-gpu","label":"MNIST tutorial: multiclass ANN with DataLoader, mini-batches, GPU"},{"id":"synthetic-regression-example-why-visualization-matters-conceptually","label":"Synthetic regression example: why visualization matters (conceptually)"},{"id":"hyperparameters-experimentation-not-philosophy","label":"Hyperparameters: \u201cexperimentation, not philosophy\u201d"}],"html":"<div class=\\"wrap\\">\\n\\n  <header class=\\"hero\\">\\n    \\n    <p class=\\"subtitle\\">\\n      A student-friendly tutorial that reconstructs the lecture ideas: <b>why neural networks exist</b>, how they generalize\\n      linear models, why activation functions matter, how <b>backpropagation</b> works (chain rule!), and how this connects\\n      to practical PyTorch code for <b>multiclass image classification</b>.\\n    </p>\\n    <div class=\\"tr-note\\">\\n      <strong>Optional reference edition</strong>\\n      This chapter presents the concepts from\\n      <a href=\\"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts\\">Chapter 1</a> and\\n      <a href=\\"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging\\">Chapter 2</a> into one long\\n      reference article. If you are reading the teaching path in order, treat\\n      this as a recap/reference rather than a separate required lesson.\\n    </div>\\n    <div class=\\"badge-row\\">\\n      <span class=\\"badge\\"><b>Task types</b>: regression \xb7 binary class \xb7 multiclass class</span>\\n      <span class=\\"badge\\"><b>Core math</b>: logits \xb7 sigmoid \xb7 softmax \xb7 cross-entropy \xb7 chain rule</span>\\n      <span class=\\"badge\\"><b>Practical</b>: batching \xb7 DataLoader \xb7 GPU device \xb7 confusion matrix</span>\\n      <span class=\\"badge\\"><b>Theme</b>: readable light-mode, VS Code-ish code colors</span>\\n    </div>\\n\\n    <nav class=\\"toc\\">\\n      <div class=\\"toc-title\\">Contents</div>\\n      <ul>\\n        <li><a href=\\"#why-how\\">Why &amp; How: \u201ccan we build a brain?\u201d</a></li>\\n        <li><a href=\\"#single-neuron\\">From logistic regression to a neuron</a></li>\\n        <li><a href=\\"#networks\\">From one neuron to layers to deep networks</a></li>\\n        <li><a href=\\"#geometry\\">Neural nets as geometry solvers: linear vs nonlinear boundaries</a></li>\\n        <li><a href=\\"#activations\\">Activation functions: sigmoid, tanh, ReLU, and friends</a></li>\\n        <li><a href=\\"#backprop\\">How models learn: gradients, chain rule, backprop, vanishing gradients</a></li>\\n        <li><a href=\\"#tasks\\">Three tasks &amp; their final-layer activations (incl. multiclass)</a></li>\\n        <li><a href=\\"#softmax-ce\\">Multiclass classification: softmax + cross-entropy (and numerical stability)</a></li>\\n        <li><a href=\\"#images\\">How images are represented (RGB, grayscale, quantization, flattening)</a></li>\\n        <li><a href=\\"#mnist\\">MNIST tutorial: DataLoader, mini-batches, GPU, accuracy, confusion matrix</a></li>\\n        <li><a href=\\"#synthetic\\">Synthetic regression example (why visualization matters)</a></li>\\n        <li><a href=\\"#experimentation\\">Hyperparameters &amp; the \u201cexperimentation, not philosophy\u201d rule</a></li>\\n      </ul>\\n    </nav>\\n  </header>\\n\\n  \x3c!-- WHY / HOW --\x3e\\n  <section id=\\"why-how\\">\\n    <h2 id=\\"why-how-why-this-topic-is-so-interesting\\">Why? How? Why this topic is so interesting</h2>\\n\\n    <div class=\\"grid2\\">\\n      <div>\\n        <p>\\n          The phrase <span class=\\"inline-hi blue\\"><b>artificial neural network</b></span> comes from a big idea:\\n          biological brains are made of neurons that communicate using electrical and chemical signals.\\n          Once you accept that a brain is a <i>physical</i> information-processing system, a natural question appears:\\n        </p>\\n\\n        <div class=\\"callout info\\">\\n          <div class=\\"title\\">The motivating question</div>\\n          <p style=\\"margin:0;\\">\\n            If a brain is \u201ca kind of computer\u201d, can we simulate networks of neurons on a computer to create\\n            <b>artificial intelligence</b>?\\n          </p>\\n        </div>\\n\\n        <p>\\n          Of course this is a simplification\u2014real brains are messy: many kinds of neurons, many regions,\\n          and connections that crisscross in complex ways. But for a computational model, we start with a\\n          deliberately simplified neuron, connect many of them, and see what the system can learn.\\n        </p>\\n\\n        <div class=\\"callout warn\\">\\n          <div class=\\"title\\">Two network \u201cwiring\u201d patterns</div>\\n          <ul class=\\"checklist\\">\\n            <li><b>Feedforward</b>: information flows layer by layer from input to output.</li>\\n            <li><b>Recurrent / feedback</b>: connections go from a later layer back to an earlier layer (a \u201cloop\u201d).</li>\\n          </ul>\\n          <p class=\\"mini\\" style=\\"margin:8px 0 0;\\">\\n            This tutorial focuses on <b>feedforward</b> networks (also called \u201cMLPs\u201d).\\n          </p>\\n        </div>\\n      </div>\\n\\n      <figure>\\n        <img loading=\\"lazy\\" alt=\\"Activation functions overview\\" src=\\"/tutorials/images/external/ActivationFunctions-1bbfdfea2f-fallback.svg\\">\\n        <figcaption>\\n          A compact overview of classic and modern activation functions (sigmoid, tanh, ReLU, leaky ReLU, \u2026).\\n          Source: <a href=\\"https://commons.wikimedia.org/wiki/File:ActivationFunctions.svg\\">Wikimedia Commons</a>.\\n        </figcaption>\\n      </figure>\\n    </div>\\n  </section>\\n\\n  \x3c!-- SINGLE NEURON --\x3e\\n  <section id=\\"single-neuron\\">\\n    <h2 id=\\"from-logistic-regression-to-a-neuron\\">From logistic regression to a \u201cneuron\u201d</h2>\\n\\n    <p>\\n      The lecture connects a <b>single logistic regression model</b> to a simplified neuron:\\n      the model computes a weighted sum, adds a bias (threshold), then passes it through a squashing nonlinearity\\n      (sigmoid) and finally makes a binary decision.\\n    </p>\\n\\n    <div class=\\"math\\">\\n      <div class=\\"eq-label\\">Single neuron (binary classification)</div>\\n      $$a = \\\\mathbf{w}^\\\\top \\\\mathbf{x} + b \\\\quad\\\\text{(activation / logit)}$$\\n      $$\\\\hat{p} = \\\\sigma(a) = \\\\frac{1}{1 + e^{-a}} \\\\quad\\\\text{(probability of class 1)}$$\\n      $$\\\\hat{y} = \\\\mathbb{1}[\\\\hat{p} \\\\ge 0.5] \\\\quad\\\\text{(predict 1 if prob \u2265 0.5)}$$\\n    </div>\\n\\n    <div class=\\"grid2\\">\\n      <div>\\n        <div class=\\"callout ok\\">\\n          <div class=\\"title\\">Interpretation</div>\\n          <p style=\\"margin:0;\\">\\n            $\\\\mathbf{w}$ controls how strongly each input feature influences the decision.\\n            $b$ shifts the decision threshold.\\n          </p>\\n        </div>\\n\\n        <p>\\n          In biology, neurons sum incoming signals through synapses. Some synapses are \u201cstrong\u201d (large magnitude weight),\\n          others \u201cweak\u201d (small weight). Some are excitatory (positive weight), others inhibitory (negative weight).\\n          A neuron either \u201cfires\u201d or does not (an all-or-nothing spike), which resembles a binary decision.\\n        </p>\\n        <p class=\\"mini\\">\\n          This is an analogy, not a claim that artificial neurons model biology faithfully. The useful engineering abstraction is:\\n          weighted inputs + bias + nonlinearity + learnable parameters.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img loading=\\"lazy\\" alt=\\"Logistic sigmoid curve\\" src=\\"/tutorials/images/external/Logistic-curve-0ea4e59f85.svg\\">\\n        <figcaption>\\n          The logistic sigmoid $\\\\sigma(x)$. Source: <a href=\\"https://commons.wikimedia.org/wiki/File:Logistic-curve.svg\\">Wikimedia Commons</a>.\\n        </figcaption>\\n      </figure>\\n    </div>\\n  </section>\\n\\n  \x3c!-- NETWORKS --\x3e\\n  <section id=\\"networks\\">\\n    <h2 id=\\"from-one-neuron-to-layers-to-deep-networks\\">From one neuron to layers to deep networks</h2>\\n\\n    <p>\\n      One neuron can only compute one feature. The next step is to use <b>many neurons in parallel</b>.\\n      A whole layer can learn many different features from the same input.\\n    </p>\\n\\n    <div class=\\"math\\">\\n      <div class=\\"eq-label\\">One hidden layer (vectorized)</div>\\n      $$\\\\mathbf{a}^{(1)} = \\\\mathbf{W}^{(1)}\\\\mathbf{x} + \\\\mathbf{b}^{(1)}$$\\n      $$\\\\mathbf{z}^{(1)} = \\\\phi\\\\!\\\\left(\\\\mathbf{a}^{(1)}\\\\right) \\\\quad\\\\text{(apply activation element-wise)}$$\\n      $$\\\\mathbf{a}^{(2)} = \\\\mathbf{W}^{(2)}\\\\mathbf{z}^{(1)} + \\\\mathbf{b}^{(2)}$$\\n    </div>\\n\\n    <p class=\\"muted\\">\\n      Notation note: the lecture uses superscripts $(1),(2),\\\\dots,(L)$ for layer index,\\n      and often uses $L$ for the total number of layers.\\n    </p>\\n\\n    <div class=\\"callout info\\">\\n      <div class=\\"title\\">Why matrices?</div>\\n      <p style=\\"margin:0;\\">\\n        With multiple neurons per layer, writing sums like $w_1x_1 + \\\\dots + w_Dx_D$ becomes unreadable.\\n        Matrices let us compute all neurons\u2019 weighted sums efficiently in one operation.\\n      </p>\\n    </div>\\n\\n    <div class=\\"hr\\"></div>\\n\\n    <h3 id=\\"a-helpful-perspective-a-sequence-of-feature-transformations\\">A helpful perspective: \u201ca sequence of feature transformations\u201d</h3>\\n    <p>\\n      A modern way to think about a deep network:\\n      each layer transforms the representation (features) into a new representation.\\n      Early layers learn simple patterns; later layers can combine them into more complex ones.\\n      This \u201cfeature hierarchy\u201d is part of why the field is called <b>deep learning</b>.\\n    </p>\\n\\n    <div class=\\"callout purple\\">\\n      <div class=\\"title\\">Classic example (as discussed)</div>\\n      <p style=\\"margin:0;\\">\\n        In face recognition visualizations: early layers resemble edge detectors, mid layers detect parts (eyes, nose, mouth),\\n        and later layers represent entire faces.\\n      </p>\\n    </div>\\n  </section>\\n\\n  \x3c!-- GEOMETRY --\x3e\\n  <section id=\\"geometry\\">\\n    <h2 id=\\"neural-nets-as-geometry-solvers-why-linear-models-aren-t-enough\\">Neural nets as geometry solvers: why linear models aren\u2019t enough</h2>\\n\\n    <p>\\n      The lecture repeatedly emphasizes: machine learning is a geometry problem.\\n      A linear classifier draws a hyperplane; points on different sides get different labels.\\n      But many real problems require <b>curved</b> decision boundaries.\\n    </p>\\n\\n    <div class=\\"callout warn\\">\\n      <div class=\\"title\\">Two ways to make models \u201cmore powerful\u201d</div>\\n      <ul class=\\"checklist\\">\\n        <li>Add <b>more input features</b> (feature engineering).</li>\\n        <li>Add <b>nonlinearity + layers</b> (neural networks) to create curved boundaries automatically.</li>\\n      </ul>\\n      <p class=\\"mini\\" style=\\"margin:8px 0 0;\\">\\n        Deep learning reduces the need for manual feature engineering\u2014especially for unstructured data like images, audio, and text.\\n      </p>\\n    </div>\\n\\n    <p>\\n      If you remove activation functions, a deep \u201cnetwork\u201d collapses into a linear map (a key lecture point):\\n      composing linear functions yields another linear function. Nonlinear activations are what make deep nets able to model\\n      more complex geometry.\\n    </p>\\n  </section>\\n\\n  \x3c!-- ACTIVATIONS --\x3e\\n  <section id=\\"activations\\">\\n    <h2 id=\\"activation-functions-sigmoid-tanh-relu-and-why\\">Activation functions: sigmoid \u2192 tanh \u2192 ReLU (and why)</h2>\\n\\n    <div class=\\"grid2\\">\\n      <div>\\n        <h3 id=\\"sigmoid\\">Sigmoid</h3>\\n        <p>\\n          Sigmoid maps real numbers to $(0,1)$. It is natural for <b>binary outputs</b> interpreted as probabilities.\\n          But hidden layers want their activations to be well-behaved for learning.\\n        </p>\\n\\n        <h3 id=\\"tanh-hyperbolic-tangent\\">Tanh (hyperbolic tangent)</h3>\\n        <p>\\n          Tanh is \u201csigmoid-like\u201d but centered around $0$, producing outputs in $(-1,1)$.\\n          This better matches the idea of keeping layer inputs roughly centered (the lecture connects this to standardization).\\n        </p>\\n\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">Key formulas</div>\\n          $$\\\\sigma(x) = \\\\frac{1}{1+e^{-x}}$$\\n          $$\\\\tanh(x) = \\\\frac{e^x - e^{-x}}{e^x + e^{-x}}$$\\n          <p class=\\"mini\\" style=\\"margin:6px 0 0;\\">\\n            Exercise idea from the lecture: show $\\\\tanh$ is a scaled/shifted version of sigmoid.\\n          </p>\\n        </div>\\n\\n        <h3 id=\\"relu-and-modern-activations\\">ReLU and modern activations</h3>\\n        <p>\\n          Sigmoid/tanh are smooth, but deep networks historically struggled with them because of\\n          <span class=\\"inline-hi orange\\"><b>vanishing gradients</b></span>.\\n          ReLU is not perfectly smooth at $0$, but empirically trains deep nets much better.\\n        </p>\\n\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">ReLU</div>\\n          $$\\\\mathrm{ReLU}(x) = \\\\max(0, x)$$\\n        </div>\\n\\n        <p class=\\"muted\\">\\n          The lecture mentions common variants: <b>Leaky ReLU</b> (small slope for $x&lt;0$),\\n          <b>ELU</b>, and <b>Softplus</b>. In practice, many people still use ReLU as a strong default.\\n        </p>\\n      </div>\\n\\n      <div>\\n        <figure style=\\"margin-bottom: 14px;\\">\\n          <img loading=\\"lazy\\" alt=\\"Hyperbolic tangent\\" src=\\"/tutorials/images/external/Hyperbolic_Tangent-1c12808e74-fallback.svg\\">\\n          <figcaption>\\n            $\\\\tanh(x)$ plot. Source: <a href=\\"https://commons.wikimedia.org/wiki/File:Hyperbolic_Tangent.svg\\">Wikimedia Commons</a>.\\n          </figcaption>\\n        </figure>\\n\\n        <figure>\\n          <img loading=\\"lazy\\" alt=\\"ReLU plot\\" src=\\"/tutorials/images/external/Activation_rectified_linear-6328ee6935-fallback.svg\\">\\n          <figcaption>\\n            ReLU \u201chockey stick\u201d shape. Source: <a href=\\"https://commons.wikimedia.org/wiki/File:Activation_rectified_linear.svg\\">Wikimedia Commons</a>.\\n          </figcaption>\\n        </figure>\\n      </div>\\n    </div>\\n  </section>\\n\\n  \x3c!-- BACKPROP / CHAIN RULE --\x3e\\n  <section id=\\"backprop\\">\\n    <h2 id=\\"how-models-learn-gradients-chain-rule-backprop-and-vanishing-gradients\\">How models learn: gradients, chain rule, backprop, and vanishing gradients</h2>\\n\\n    <p>\\n      Training is still \u201cminimize a loss with gradient descent,\u201d but neural networks are compositions of many functions.\\n      Backpropagation is essentially the <b>chain rule</b> applied efficiently.\\n    </p>\\n\\n    <div class=\\"grid2\\">\\n      <div>\\n        <h3 id=\\"gradient-descent-high-level\\">Gradient descent (high level)</h3>\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">Parameter update</div>\\n          $$\\\\theta \\\\leftarrow \\\\theta - \\\\eta \\\\nabla_\\\\theta \\\\mathcal{L}$$\\n          <p class=\\"mini\\" style=\\"margin:6px 0 0;\\">\\n            $\\\\eta$ is the learning rate (a hyperparameter). Too large: divergence. Too small: painfully slow.\\n          </p>\\n        </div>\\n\\n        <h3 id=\\"chain-rule-the-key-math-for-backprop\\">Chain rule (the key math for backprop)</h3>\\n        <p>\\n          If $y = f(g(x))$, then\\n          $$\\\\frac{dy}{dx} = \\\\frac{dy}{dg}\\\\cdot \\\\frac{dg}{dx}.$$\\n          For deeper compositions $f_1(f_2(\\\\dots f_L(x)\\\\dots))$ you multiply many derivatives.\\n          This multiplication is exactly what can cause gradients to shrink (vanish).\\n        </p>\\n\\n        <div class=\\"callout danger\\">\\n          <div class=\\"title\\">Vanishing gradients (as described)</div>\\n          <p style=\\"margin:0;\\">\\n            For sigmoid, the derivative is at most $0.25$. Multiplying numbers \u2264 $0.25$ many times makes the result tiny,\\n            so early layers receive almost no learning signal.\\n          </p>\\n        </div>\\n\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">Sigmoid derivative and the \u201c0.25\u201d fact</div>\\n          $$\\\\sigma\'(x) = \\\\sigma(x)\\\\left(1-\\\\sigma(x)\\\\right) \\\\le 0.25$$\\n          $$0.25^5 \\\\approx 0.00098,\\\\qquad 0.1^5 = 0.00001$$\\n        </div>\\n\\n        <p class=\\"muted\\">\\n          The lecture also mentions an older workaround: layer-wise pretraining (associated with Geoffrey Hinton and students),\\n          where layers were trained one at a time. Modern practice usually avoids this by using better activations (like ReLU)\\n          and other techniques.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img loading=\\"lazy\\" alt=\\"Chain rule diagram\\" src=\\"/tutorials/images/external/Prospects_of_Chain_Rule_of_Differentiations_and_Inverse_of_Multiple_Functions-82816139f1-fallback.svg\\">\\n        <figcaption>\\n          A diagram related to the chain rule for composite functions.\\n          Source: <a href=\\"https://commons.wikimedia.org/wiki/File:Prospects_of_Chain_Rule_of_Differentiations_and_Inverse_of_Multiple_Functions.png\\">Wikimedia Commons</a>.\\n        </figcaption>\\n      </figure>\\n    </div>\\n\\n    <div class=\\"callout info\\">\\n      <div class=\\"title\\">PyTorch connection (important practical note)</div>\\n      <p style=\\"margin:0;\\">\\n        You typically do not compute derivatives by hand. PyTorch uses automatic differentiation.\\n        Your job is to build the computation graph and call <span class=\\"kbd\\">loss.backward()</span>.\\n      </p>\\n    </div>\\n  </section>\\n\\n  \x3c!-- TASKS --\x3e\\n  <section id=\\"tasks\\">\\n    <h2 id=\\"three-tasks-and-their-final-layer-activations\\">Three tasks &amp; their final-layer activations</h2>\\n\\n    <p>\\n      A key summary from the lecture: regardless of whether the \u201cbody\u201d of your network is a linear model, MLP, CNN, or RNN,\\n      the <b>final layer</b> follows the task type.\\n    </p>\\n\\n    <div class=\\"kpi\\">\\n      <span class=\\"pill\\"><b>Regression</b>: identity (no activation)</span>\\n      <span class=\\"pill\\"><b>Binary classification</b>: sigmoid</span>\\n      <span class=\\"pill\\"><b>Multiclass classification</b>: softmax</span>\\n    </div>\\n\\n    <div class=\\"math\\">\\n      <div class=\\"eq-label\\">Final layer patterns</div>\\n      <p class=\\"mini\\" style=\\"margin:0 0 8px;\\">(Let $\\\\mathbf{a}$ be the final layer\u2019s <b>logits</b>.)</p>\\n      $$\\\\textbf{Regression:}\\\\quad \\\\hat{y} = a$$\\n      $$\\\\textbf{Binary:}\\\\quad \\\\hat{p} = \\\\sigma(a)$$\\n      $$\\\\textbf{Multiclass:}\\\\quad \\\\hat{\\\\mathbf{p}} = \\\\mathrm{softmax}(\\\\mathbf{a})$$\\n    </div>\\n\\n    <div class=\\"callout warn\\">\\n      <div class=\\"title\\">\u201cSoftmax is more general\u201d (lecture note)</div>\\n      <p style=\\"margin:0;\\">\\n        Softmax can handle $K$ classes including $K=2$, but for binary classification sigmoid is simpler and avoids redundancy.\\n      </p>\\n    </div>\\n  </section>\\n\\n  \x3c!-- SOFTMAX + CE --\x3e\\n  <section id=\\"softmax-ce\\">\\n    <h2 id=\\"multiclass-classification-softmax-cross-entropy-and-stability\\">Multiclass classification: softmax + cross-entropy (and stability)</h2>\\n\\n    <div class=\\"grid2\\">\\n      <div>\\n        <p>\\n          For $K$ classes, the final layer outputs a vector of logits $\\\\mathbf{a}\\\\in\\\\mathbb{R}^K$.\\n          We want probabilities: each is nonnegative and they sum to 1. Softmax does exactly that:\\n        </p>\\n\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">Softmax</div>\\n          $$\\\\mathrm{softmax}(\\\\mathbf{a})_k = \\\\frac{e^{a_k}}{\\\\sum_{j=1}^{K} e^{a_j}}.$$\\n          <p class=\\"mini\\" style=\\"margin:6px 0 0;\\">\\n            Numerator is always positive. Denominator sums all numerators, so probabilities sum to 1.\\n          </p>\\n        </div>\\n\\n        <p>\\n          Training uses <b>cross-entropy loss</b>. A crucial numerical stability tip (mirroring the BCE-with-logits story):\\n          you usually don\u2019t apply softmax \u201cmanually\u201d before the loss. Frameworks combine these steps to avoid overflow/underflow.\\n        </p>\\n\\n        <div class=\\"callout ok\\">\\n          <div class=\\"title\\">PyTorch rule of thumb</div>\\n          <p style=\\"margin:0;\\">\\n            Use <span class=\\"kbd\\">nn.CrossEntropyLoss</span> with raw logits (no softmax layer).\\n            It internally computes a stable log-softmax + negative log-likelihood.\\n          </p>\\n        </div>\\n\\n        <div class=\\"callout\\">\\n          <div class=\\"title\\">Probability vs calibration</div>\\n          <p style=\\"margin:0;\\">\\n            Softmax produces values that are shaped like probabilities, but a trained model can still be overconfident.\\n            Use validation data and calibration checks if the numerical confidence itself matters, not just the predicted class.\\n          </p>\\n        </div>\\n\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">Cross-entropy (one-hot target)</div>\\n          $$\\\\mathcal{L} = -\\\\sum_{k=1}^{K} y_k \\\\log(\\\\hat{p}_k).$$\\n        </div>\\n\\n        <p>\\n          For prediction, you do not need probabilities either: the class with maximum logit is the same class with maximum softmax probability.\\n          So prediction is:\\n        </p>\\n\\n        <div class=\\"math\\">\\n          <div class=\\"eq-label\\">Prediction</div>\\n          $$\\\\hat{y}=\\\\arg\\\\max_k a_k.$$\\n        </div>\\n      </div>\\n\\n      <div>\\n        <figure style=\\"margin-bottom: 14px;\\">\\n          <img loading=\\"lazy\\" alt=\\"Softmax diagram\\" src=\\"/tutorials/images/external/Softmax_en-e73c160fc6-fallback.svg\\">\\n          <figcaption>\\n            Softmax maps logits to probabilities. Source: <a href=\\"https://commons.wikimedia.org/wiki/File:Softmax_en.svg\\">Wikimedia Commons</a>.\\n          </figcaption>\\n        </figure>\\n        <figure>\\n          <img loading=\\"lazy\\" alt=\\"Confusion matrix example\\" src=\\"/tutorials/images/external/ConfusionMatrixRedBlue-5b66cb0457-fallback.svg\\">\\n          <figcaption>\\n            Confusion matrix (binary example). We\u2019ll use the same idea for multiclass (MNIST).\\n            Source: <a href=\\"https://commons.wikimedia.org/wiki/File:ConfusionMatrixRedBlue.png\\">Wikimedia Commons</a>.\\n          </figcaption>\\n        </figure>\\n      </div>\\n    </div>\\n  </section>\\n\\n  \x3c!-- IMAGES --\x3e\\n  <section id=\\"images\\">\\n    <h2 id=\\"how-images-are-represented-in-a-computer-rgb-grayscale-quantization-flattening\\">How images are represented in a computer (RGB, grayscale, quantization, flattening)</h2>\\n\\n    <p>\\n      The lecture transitions from \u201cmodel\u201d topics to \u201cdata\u201d topics: deep learning shines on <b>unstructured data</b>\\n      like images, sound, and text. But how does an image become an input vector?\\n    </p>\\n\\n    <h3 id=\\"rgb-three-numbers-per-pixel\\">RGB: three numbers per pixel</h3>\\n    <div class=\\"grid2\\">\\n      <div>\\n        <p>\\n          A color image has <b>height</b> and <b>width</b>, but each pixel also has color.\\n          A common representation is <span class=\\"inline-hi green\\"><b>RGB</b></span> (Red, Green, Blue).\\n          Each pixel stores how much red, green, and blue it contains.\\n        </p>\\n        <p>\\n          So a color image is naturally a 3D tensor:\\n          $$A[i,j,k],\\\\quad k\\\\in\\\\{R,G,B\\\\}.$$\\n          A dataset of $N$ images becomes a 4D tensor:\\n          $$A[n,i,j,k].$$\\n        </p>\\n\\n        <div class=\\"callout info\\">\\n          <div class=\\"title\\">Quantization (0 to 255)</div>\\n          <p style=\\"margin:0;\\">\\n            Pixel intensities are often stored as integers in $\\\\{0,\\\\dots,255\\\\}$ (8 bits per channel).\\n            That\u2019s $256^3 \\\\approx 16.8$ million possible RGB colors.\\n          </p>\\n        </div>\\n\\n        <p>\\n          A quick size estimate from the lecture: a raw $500\\\\times 500$ RGB image stores\\n          $500\\\\cdot 500\\\\cdot 3 = 750{,}000$ bytes $\\\\approx 732$ KB. Compression (JPEG/PNG) reduces this significantly.\\n        </p>\\n\\n        <div class=\\"callout warn\\">\\n          <div class=\\"title\\">Hex colors (web dev connection)</div>\\n          <p style=\\"margin:0;\\">\\n            Hex colors like <span class=\\"kbd\\">#RRGGBB</span> are just the same 8-bit values written in base-16.\\n          </p>\\n        </div>\\n      </div>\\n\\n      <figure>\\n        <img loading=\\"lazy\\" alt=\\"RGB cube\\" src=\\"/tutorials/images/external/RGB_color_cube-679a44f6bd-fallback.svg\\">\\n        <figcaption>\\n          RGB color cube visualization. Source: <a href=\\"https://commons.wikimedia.org/wiki/File:RGB_color_cube.svg\\">Wikimedia Commons</a>.\\n        </figcaption>\\n      </figure>\\n    </div>\\n\\n    <h3 id=\\"grayscale-images\\">Grayscale images</h3>\\n    <p>\\n      If an image has no color channels, you only store one intensity per pixel. Then an image is a 2D array (height \xd7 width).\\n      MNIST digits are grayscale, so each image is $28\\\\times 28$.\\n    </p>\\n\\n    <h3 id=\\"scaling-to-0-1-for-neural-networks\\">Scaling to $[0,1]$ for neural networks</h3>\\n    <p>\\n      The lecture notes a common preprocessing step: convert uint8 pixel values in $[0,255]$ to floating point values in $[0,1]$.\\n      This keeps inputs small and numerically convenient.\\n    </p>\\n\\n    <h3 id=\\"flattening-the-dumb-but-simple-trick\\">Flattening: the \u201cdumb but simple\u201d trick</h3>\\n    <p>\\n      A fully-connected network expects a 2D array of shape $(N, D)$.\\n      The lecture\u2019s simple solution: <b>flatten</b> each $28\\\\times 28$ image into a length-$784$ vector\\n      (scan pixels left-to-right, top-to-bottom).\\n    </p>\\n\\n    <div class=\\"callout warn\\">\\n      <div class=\\"title\\">Important practical note</div>\\n      <p style=\\"margin:0;\\">\\n        Flattening ignores spatial structure. Convolutional neural networks (CNNs) usually perform better for vision,\\n        but flattening is a great first step to learn the training pipeline.\\n      </p>\\n    </div>\\n\\n    <div class=\\"grid2\\" style=\\"margin-top: 1rem;\\">\\n      <div>\\n        <h4>Mini example: a $3\\\\times 3$ grayscale image</h4>\\n        <p class=\\"note\\">\\n          Think of the image as a matrix $I\\\\in\\\\mathbb{R}^{3\\\\times 3}$.\\n          Flattening (also called <i>vectorization</i>) stacks pixels into a vector $x\\\\in\\\\mathbb{R}^{9}$.\\n        </p>\\n\\n        <table class=\\"matrix\\" aria-label=\\"3 by 3 image matrix\\">\\n          <caption>Image matrix $I$ (each entry is one pixel intensity)</caption>\\n          <tbody>\\n            <tr><td>$I_{11}$</td><td>$I_{12}$</td><td>$I_{13}$</td></tr>\\n            <tr><td>$I_{21}$</td><td>$I_{22}$</td><td>$I_{23}$</td></tr>\\n            <tr><td>$I_{31}$</td><td>$I_{32}$</td><td>$I_{33}$</td></tr>\\n          </tbody>\\n        </table>\\n\\n        <p class=\\"note\\" style=\\"margin-top:0.6rem;\\">\\n          A common convention (used in the lecture) is row-major order:\\n          $$x = \\\\mathrm{vec}(I) = [I_{11}, I_{12}, I_{13}, I_{21}, I_{22}, I_{23}, I_{31}, I_{32}, I_{33}]^\\\\top.$$\\n          In general, for a $H\\\\times W$ grayscale image:\\n          $$x_{(i-1)W + j} = I_{ij},\\\\quad 1\\\\le i\\\\le H,\\\\; 1\\\\le j\\\\le W.$$\\n        </p>\\n      </div>\\n\\n      <div>\\n        <h4>For MNIST: $28\\\\times 28 \\\\to 784$</h4>\\n        <p class=\\"note\\">\\n          MNIST is grayscale, so $C=1$. Each sample arrives as a tensor of shape $[B, 28, 28]$ (or sometimes $[B,1,28,28]$),\\n          and we reshape it into $[B, 784]$ before sending it into a fully-connected layer.\\n        </p>\\n\\n        <pre><code class=\\"language-python\\"># x: [B, 28, 28]\\nx = x.view(x.size(0), -1)   # [B, 784]  (the \u201cdumb but simple\u201d trick)</code></pre>\\n\\n        <div class=\\"svgbox\\" style=\\"margin-top:0.9rem;\\">\\n          <svg viewBox=\\"0 0 640 220\\" width=\\"100%\\" role=\\"img\\" aria-label=\\"Flatten diagram\\">\\n            <defs>\\n              <marker id=\\"arrow\\" markerWidth=\\"12\\" markerHeight=\\"12\\" refX=\\"10\\" refY=\\"6\\" orient=\\"auto\\">\\n                <path d=\\"M0,0 L12,6 L0,12 Z\\" fill=\\"#6b7280\\"></path>\\n              </marker>\\n            </defs>\\n\\n            \x3c!-- Left grid --\x3e\\n            <rect x=\\"20\\" y=\\"35\\" width=\\"180\\" height=\\"150\\" rx=\\"12\\" fill=\\"#ffffff\\" stroke=\\"#d1d5db\\"></rect>\\n            <text x=\\"110\\" y=\\"25\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#374151\\">image I</text>\\n\\n            \x3c!-- 3x3 cells --\x3e\\n            <g stroke=\\"#e5e7eb\\">\\n              <line x1=\\"80\\" y1=\\"35\\" x2=\\"80\\" y2=\\"185\\"></line>\\n              <line x1=\\"140\\" y1=\\"35\\" x2=\\"140\\" y2=\\"185\\"></line>\\n              <line x1=\\"20\\" y1=\\"85\\" x2=\\"200\\" y2=\\"85\\"></line>\\n              <line x1=\\"20\\" y1=\\"135\\" x2=\\"200\\" y2=\\"135\\"></line>\\n            </g>\\n            <g font-size=\\"12\\" fill=\\"#111827\\" font-family=\\"ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace\\">\\n              <text x=\\"50\\" y=\\"68\\" text-anchor=\\"middle\\">p1</text>\\n              <text x=\\"110\\" y=\\"68\\" text-anchor=\\"middle\\">p2</text>\\n              <text x=\\"170\\" y=\\"68\\" text-anchor=\\"middle\\">p3</text>\\n              <text x=\\"50\\" y=\\"118\\" text-anchor=\\"middle\\">p4</text>\\n              <text x=\\"110\\" y=\\"118\\" text-anchor=\\"middle\\">p5</text>\\n              <text x=\\"170\\" y=\\"118\\" text-anchor=\\"middle\\">p6</text>\\n              <text x=\\"50\\" y=\\"168\\" text-anchor=\\"middle\\">p7</text>\\n              <text x=\\"110\\" y=\\"168\\" text-anchor=\\"middle\\">p8</text>\\n              <text x=\\"170\\" y=\\"168\\" text-anchor=\\"middle\\">p9</text>\\n            </g>\\n\\n            \x3c!-- Arrow --\x3e\\n            <line x1=\\"220\\" y1=\\"110\\" x2=\\"390\\" y2=\\"110\\" stroke=\\"#6b7280\\" stroke-width=\\"3\\" marker-end=\\"url(#arrow)\\"></line>\\n            <text x=\\"305\\" y=\\"95\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#374151\\">flatten / reshape</text>\\n\\n            \x3c!-- Right vector --\x3e\\n            <rect x=\\"410\\" y=\\"35\\" width=\\"210\\" height=\\"150\\" rx=\\"12\\" fill=\\"#ffffff\\" stroke=\\"#d1d5db\\"></rect>\\n            <text x=\\"515\\" y=\\"25\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#374151\\">vector x = vec(I)</text>\\n\\n            \x3c!-- Vector slots --\x3e\\n            <g stroke=\\"#e5e7eb\\">\\n              <line x1=\\"410\\" y1=\\"65\\" x2=\\"620\\" y2=\\"65\\"></line>\\n              <line x1=\\"410\\" y1=\\"95\\" x2=\\"620\\" y2=\\"95\\"></line>\\n              <line x1=\\"410\\" y1=\\"125\\" x2=\\"620\\" y2=\\"125\\"></line>\\n              <line x1=\\"410\\" y1=\\"155\\" x2=\\"620\\" y2=\\"155\\"></line>\\n            </g>\\n            <g font-size=\\"12\\" fill=\\"#111827\\" font-family=\\"ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace\\">\\n              <text x=\\"435\\" y=\\"55\\">[p1, p2, p3, p4, p5, p6, p7, p8, p9]</text>\\n            </g>\\n          </svg>\\n          <div class=\\"note\\" style=\\"margin-top:0.5rem;\\">\\n            This is not \u201cfeature engineering\u201d\u2014it\u2019s only changing the <i>shape</i> of the data so a dense layer can consume it.\\n          </div>\\n        </div>\\n      </div>\\n    </div>\\n\\n  </section>\\n\\n  \x3c!-- MNIST --\x3e\\n  \\n  <section id=\\"mnist\\">\\n    <h2 id=\\"mnist-tutorial-multiclass-ann-with-dataloader-mini-batches-gpu\\">MNIST tutorial: multiclass ANN with DataLoader, mini-batches, GPU</h2>\\n\\n    <figure class=\\"figure\\" style=\\"margin-top:0.75rem;\\">\\n      <img src=\\"/tutorials/images/external/MnistExamples-d4e8cf54a6.png\\" alt=\\"Samples from the MNIST handwritten digit dataset\\">\\n      <figcaption>\\n        Samples from the MNIST test dataset (each digit is a $28\\\\times 28$ grayscale image). Source: Wikimedia Commons (CC BY-SA 4.0).\\n      </figcaption>\\n    </figure>\\n\\n    <div class=\\"grid2\\">\\n\\n      <div>\\n        <p>\\n          MNIST is a classic dataset of handwritten digits (0\u20139). This is a <b>multiclass classification</b> problem\\n          with $K=10$ classes. The training set has $60{,}000$ images and the test set has $10{,}000$ images.\\n        </p>\\n\\n        <div class=\\"callout info\\">\\n          <div class=\\"title\\">Why mini-batches?</div>\\n          <p style=\\"margin:0;\\">\\n            Large datasets may not fit in memory. So we compute loss/gradients on small batches.\\n            A batch is a random sample\u2014its gradient is a noisy but useful estimate of the full gradient.\\n          </p>\\n        </div>\\n      </div>\\n\\n      <figure>\\n        <img loading=\\"lazy\\" alt=\\"MNIST example\\" src=\\"/tutorials/images/external/MnistExamples-bca2db2c9d.png\\">\\n        <figcaption>\\n          MNIST samples. Source: <a href=\\"https://commons.wikimedia.org/wiki/File:MnistExamples.png\\">Wikimedia Commons</a>.\\n        </figcaption>\\n      </figure>\\n    </div>\\n\\n    <h3 id=\\"pytorch-code-end-to-end-clean-baseline\\">PyTorch code: end-to-end (clean baseline)</h3>\\n    <p class=\\"muted\\">\\n      This code matches the lecture flow: load MNIST from <span class=\\"kbd\\">torchvision</span>, scale to $[0,1]$ via <span class=\\"kbd\\">ToTensor()</span>,\\n      flatten to 784 features, build a small feedforward net, train with mini-batches, evaluate with accuracy and confusion matrix.\\n    </p>\\n\\n<pre><code class=\\"language-python\\">import torch\\nimport torch.nn as nn\\nfrom torch.utils.data import DataLoader\\nfrom torchvision import datasets, transforms\\n\\n# -------------------------\\n# 1) Data\\n# -------------------------\\ntransform = transforms.ToTensor()  # converts uint8 [0..255] to float32 [0..1]\\n\\ntrain_ds = datasets.MNIST(root=\\".\\", train=True, transform=transform, download=True)\\ntest_ds  = datasets.MNIST(root=\\".\\", train=False, transform=transform, download=True)\\n\\nbatch_size = 128\\ntrain_loader = DataLoader(train_ds, batch_size=batch_size, shuffle=True)\\ntest_loader  = DataLoader(test_ds, batch_size=batch_size, shuffle=False)\\n\\n# -------------------------\\n# 2) Model (flatten -&gt; FC -&gt; ReLU -&gt; FC)\\n# -------------------------\\nmodel = nn.Sequential(\\n    nn.Linear(28 * 28, 128),\\n    nn.ReLU(),\\n    nn.Linear(128, 10)  # logits for 10 classes\\n)\\n\\n# -------------------------\\n# 3) Device (GPU if available)\\n# -------------------------\\ndevice = torch.device(\\"cuda:0\\" if torch.cuda.is_available() else \\"cpu\\")\\nmodel.to(device)\\n\\n# -------------------------\\n# 4) Loss + Optimizer\\n# -------------------------\\ncriterion = nn.CrossEntropyLoss()  # expects logits, applies stable log-softmax internally\\noptimizer = torch.optim.Adam(model.parameters(), lr=1e-3)\\n\\n# -------------------------\\n# 5) Train / Eval helpers\\n# -------------------------\\ndef accuracy_from_logits(logits, y):\\n    # logits: [B, 10], y: [B]\\n    preds = torch.argmax(logits, dim=1)\\n    return (preds == y).float().mean().item()\\n\\ndef run_epoch(loader, training: bool):\\n    total_loss = 0.0\\n    total_correct = 0\\n    total_seen = 0\\n\\n    if training:\\n        model.train()\\n    else:\\n        model.eval()\\n\\n    for x, y in loader:\\n        x = x.to(device)          # [B, 1, 28, 28]\\n        y = y.to(device)          # [B]\\n\\n        x = x.view(x.size(0), -1) # flatten -&gt; [B, 784]\\n\\n        if training:\\n            optimizer.zero_grad()\\n\\n        with torch.set_grad_enabled(training):\\n            logits = model(x)               # [B, 10]\\n            loss = criterion(logits, y)\\n\\n            if training:\\n                loss.backward()\\n                optimizer.step()\\n\\n        total_loss += loss.item() * x.size(0)\\n        total_correct += (torch.argmax(logits, dim=1) == y).sum().item()\\n        total_seen += x.size(0)\\n\\n    avg_loss = total_loss / total_seen\\n    acc = total_correct / total_seen\\n    return avg_loss, acc\\n\\n# -------------------------\\n# 6) Training loop\\n# -------------------------\\nepochs = 10\\nfor ep in range(1, epochs + 1):\\n    train_loss, train_acc = run_epoch(train_loader, training=True)\\n    test_loss,  test_acc  = run_epoch(test_loader, training=False)\\n    print(f\\"Epoch {ep:02d} | train loss {train_loss:.4f} acc {train_acc:.4f} | \\"\\n          f\\"test loss {test_loss:.4f} acc {test_acc:.4f}\\")\\n</code></pre>\\n\\n    <h3 id=\\"confusion-matrix-and-what-does-the-model-confuse\\">Confusion matrix and \u201cwhat does the model confuse?\u201d</h3>\\n    <p>\\n      The lecture suggests going beyond accuracy: find which digits are confused.\\n      A confusion matrix counts how often each true label is predicted as each label.\\n      (You often expect large values on the diagonal.)\\n    </p>\\n\\n<pre><code class=\\"language-python\\">import numpy as np\\nfrom sklearn.metrics import confusion_matrix\\n\\nmodel.eval()\\nall_preds = []\\nall_true = []\\n\\nwith torch.no_grad():\\n    for x, y in test_loader:\\n        x = x.to(device).view(x.size(0), -1)\\n        logits = model(x)\\n        preds = torch.argmax(logits, dim=1).cpu().numpy()\\n        all_preds.append(preds)\\n        all_true.append(y.numpy())\\n\\ny_pred = np.concatenate(all_preds)\\ny_true = np.concatenate(all_true)\\n\\ncm = confusion_matrix(y_true, y_pred)\\nprint(cm)  # rows=true labels, cols=pred labels\\n</code></pre>\\n\\n    <div class=\\"callout ok\\">\\n      <div class=\\"title\\">Lecture-style interpretation idea</div>\\n      <p style=\\"margin:0;\\">\\n        If the matrix shows \u201c4 is often predicted as 9\u201d, look at example images:\\n        some handwritten 4s really do resemble 9s.\\n      </p>\\n    </div>\\n\\n    <p class=\\"mini\\">\\n      Also mentioned: the dataset pipeline uses <span class=\\"kbd\\">transform=ToTensor()</span>.\\n      That\u2019s why printing raw <span class=\\"kbd\\">train_ds.data</span> shows integers 0\u2013255,\\n      but batches from the DataLoader are floats in 0\u20131.\\n    </p>\\n  </section>\\n\\n  \x3c!-- SYNTHETIC --\x3e\\n  <section id=\\"synthetic\\">\\n    <h2 id=\\"synthetic-regression-example-why-visualization-matters-conceptually\\">Synthetic regression example: why visualization matters (conceptually)</h2>\\n\\n    <p>\\n      The lecture argues that synthetic datasets are valuable because you can <b>see</b> where a model succeeds or fails.\\n      For a 2D input $(x_1, x_2)$ you can even visualize the target function as a 3D surface.\\n    </p>\\n\\n    <div class=\\"callout warn\\">\\n      <div class=\\"title\\">Note about plots</div>\\n      <p style=\\"margin:0;\\">\\n        This page avoids generating custom plots (per your request). The code below shows the standard approach,\\n        but we do not embed a plot image unless we have a reliable reference image for that exact function.\\n      </p>\\n    </div>\\n\\n<pre><code class=\\"language-python\\">import numpy as np\\nimport torch\\nimport torch.nn as nn\\n\\n# Synthetic data: x in [-3, 3]^2, y = cos(2*x1) + cos(3*x2)\\nN = 10_000\\nX = (np.random.rand(N, 2) * 6.0) - 3.0\\ny = np.cos(2 * X[:, 0]) + np.cos(3 * X[:, 1])\\n\\nX_t = torch.tensor(X, dtype=torch.float32)\\ny_t = torch.tensor(y, dtype=torch.float32).view(-1, 1)\\n\\nmodel = nn.Sequential(\\n    nn.Linear(2, 128),\\n    nn.ReLU(),\\n    nn.Linear(128, 1)  # regression: no activation\\n)\\n\\nopt = torch.optim.Adam(model.parameters(), lr=3e-2)\\nloss_fn = nn.MSELoss()\\n\\nfor ep in range(200):\\n    opt.zero_grad()\\n    preds = model(X_t)\\n    loss = loss_fn(preds, y_t)\\n    loss.backward()\\n    opt.step()\\n</code></pre>\\n  </section>\\n\\n  \x3c!-- EXPERIMENTATION --\x3e\\n  <section id=\\"experimentation\\">\\n    <h2 id=\\"hyperparameters-experimentation-not-philosophy\\">Hyperparameters: \u201cexperimentation, not philosophy\u201d</h2>\\n\\n    <p>\\n      The transcript ends with an important mindset: there is no universal formula for choosing learning rates,\\n      number of layers, hidden units, activations, optimizers, etc. These are <b>hyperparameters</b>.\\n      You discover what works by testing and observing.\\n    </p>\\n\\n    <div class=\\"callout info\\">\\n      <div class=\\"title\\">Practical strategy (matches the lecture)</div>\\n      <ul class=\\"checklist\\">\\n        <li>Start with common defaults (Adam, ReLU, learning rates like $10^{-3}$).</li>\\n        <li>Run experiments; plot loss/accuracy curves; watch for divergence or slow learning.</li>\\n        <li>Use literature in your domain as a guide for reasonable ranges.</li>\\n        <li>Remember: rules of thumb change; results are empirical.</li>\\n      </ul>\\n    </div>\\n\\n    <p class=\\"muted\\">\\n      The \u201cdon\u2019t predict the outcome with your mind\u2014run the program\u201d theme is a reminder that deep learning is an experimental science.\\n      When you can test an idea quickly, testing beats guessing.\\n    </p>\\n\\n    <div class=\\"callout purple\\">\\n      <div class=\\"title\\">Optional playground (mentioned in spirit)</div>\\n      <p style=\\"margin:0;\\">\\n        Interactive intuition builder: <a href=\\"https://playground.tensorflow.org/\\" target=\\"_blank\\" rel=\\"noopener\\">TensorFlow Playground</a>.\\n        Try changing the number of layers/units and watch nonlinear decision boundaries appear.\\n      </p>\\n    </div>\\n  </section>\\n\\n  <div class=\\"footer\\">\\n    This optional reference consolidates the FFN concept and training path in\\n    one chapter. Source credits are retained where applicable.\\n  </div>\\n\\n</div>"}'),l={title:"Neural Networks (ANNs): From a Single Neuron to Multiclass Image Classification",slug:"/part5-deep-learning-and-llms/03-ffn-canonical-merged",description:"A student-friendly tutorial that reconstructs the lecture ideas: why neural networks exist, how they generalize linear models, why activation functions matter, how backpropagation works (chain rule!), and how this con...",sidebar_label:"3. FFN single-chapter reference",pagination_label:"3. FFN single-chapter reference",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},m=[];function p(e){return(0,t.jsx)(o.A,{content:r})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(p,{...e})}):p()}}}]);